var SS_SERVER_ORIGINATOR_DESCRIPTION			= "Веб-сайт: %s";
var SS_SERVER_READ_KEY_DESCRIPTION				= "Ідентифікація клієнта у системі %s";
var SS_SERVER_SIGN_HASH_DESCRIPTION				= "Підпис даних у системі %s";
var SS_SERVER_GEN_KEY_DESCRIPTION				= "Генерація ос. ключа у системі %s";
var SS_SERVER_QR_CODE_SCALE						= 3;

//===============================================================================

var EndUserKSPKey = function(
	kspSettings, userId, keyId, signAlgos, certIssuerCN, certs, ownerInfo) {
	this.kspSettings = kspSettings;
	this.userId = userId;
	this.keyId = keyId;
	this.signAlgos = signAlgos;
	this.certIssuerCN = certIssuerCN;
	this.certs = certs;
	this.ownerInfo = ownerInfo;
};

//-------------------------------------------------------------------------------

var EndUserKSPStatus = function() {
	this.code = null;
	this.message = null;
};

//-------------------------------------------------------------------------------

var EndUserKSPRequest = function(command, parameters) {
	this.command = command;
	this.parameters = parameters;
};

//-------------------------------------------------------------------------------

var EndUserKSPResponse = function() {
	this.data = null;
	this.error = null;
};

//-------------------------------------------------------------------------------

var EndUserKSPError = function(code, kspStatus) {
	this.code = code;
	this.kspStatus = kspStatus;
};

//-------------------------------------------------------------------------------

var EndUserKSPOperationConfirmation = function(onSuccess, onError) {
	this.onSuccess = onSuccess;
	this.onError = onError;
};

//===============================================================================

var EndUserKSP = function(url, KSPs, euSign, context, onEvent) {
	this.m_url = url;
	this.m_KSPs = KSPs;
	this.m_euSign = euSign;
	this.m_context = context;
	this.m_keyContext = null;
	this.m_onEvent = onEvent;
	this.m_signType = EU_SIGN_TYPE_CADES_BES;
	this.m_activeOperation = false;
};

//===============================================================================

EndUserKSP.EU_KSP_KYIVSTAR						= 1;
EndUserKSP.EU_KSP_VODAFONE						= 2;
EndUserKSP.EU_KSP_LIFECELL						= 3;
EndUserKSP.EU_KSP_IIT							= 4;
EndUserKSP.EU_KSP_UKEY							= 5;
EndUserKSP.EU_KSP_PB							= 6;
EndUserKSP.EU_KSP_DIIA							= 7;

EndUserKSP.EU_KSP_OPERATION_TYPE_READ_PK		= 1;
EndUserKSP.EU_KSP_OPERATION_TYPE_SIGN_HASH		= 2;

EndUserKSP.EU_KSP_CERT_ISSUER_CN_KYIVSTAR		= "CA of the Justice of Ukraine";
EndUserKSP.EU_KSP_CERT_ISSUER_CN_VODAFONE		= "АЦСК \"MASTERKEY\" ТОВ \"АРТ-МАСТЕР\"";
EndUserKSP.EU_KSP_CERT_ISSUER_CN_LIFECELL		= "АЦСК \"MASTERKEY\" ТОВ \"АРТ-МАСТЕР\"";

EndUserKSP.EU_KSP_COMMAND_INITIALIZE_READ_PKEY			= "initializeReadPKey";
EndUserKSP.EU_KSP_COMMAND_GET_READ_PKEY_RESULT			= "getReadPKeyResult";
EndUserKSP.EU_KSP_COMMAND_INITIALIZE_SIGN_HASH			= "initializeSignHash";
EndUserKSP.EU_KSP_COMMAND_GET_SIGN_HASH_RESULT			= "getSignHashResult";
EndUserKSP.EU_KSP_COMMAND_INITIALIZE_SIGN_HASHES		= "initializeSignHashes";
EndUserKSP.EU_KSP_COMMAND_GET_SIGN_HASHES_RESULT		= "getSignHashesResult";
EndUserKSP.EU_KSP_COMMAND_INITIALIZE_USER_REGISTRATION	= 'initializeUserRegistration';
EndUserKSP.EU_KSP_COMMAND_GET_USER_REGISTRATION_RESULT	= 'getUserRegistrationResult';

EndUserKSP.EU_KSP_STATUS_REQUEST_OK				= 100;
EndUserKSP.EU_KSP_STATUS_WRONG_PARAM			= 101;
EndUserKSP.EU_KSP_STATUS_EXPIRED_TRANSACTION	= 208;
EndUserKSP.EU_KSP_STATUS_USER_CANCEL			= 401;
EndUserKSP.EU_KSP_STATUS_NO_CERT_FOUND			= 422;
EndUserKSP.EU_KSP_STATUS_ERROR_CERTIFICATE		= 425;
EndUserKSP.EU_KSP_STATUS_OUSTANDING_TRANSACTION	= 504;
EndUserKSP.EU_KSP_STATUS_INTERNAL_ERROR			= 900;

EndUserKSP.EU_KSP_COMMAND_POLLING_INTERVAL		= 1;
EndUserKSP.EU_KSP_COMMAND_EXPIRE_TIME			= 5 * 60;

EndUserKSP.EU_KSP_SIGN_CONTAINER_UNKNOWN		= 0;
EndUserKSP.EU_KSP_SIGN_CONTAINER_CADES			= 1;
EndUserKSP.EU_KSP_SIGN_CONTAINER_XADES			= 2;
EndUserKSP.EU_KSP_SIGN_CONTAINER_PADES			= 3;
EndUserKSP.EU_KSP_SIGN_CONTAINER_ASIC_S			= 4;
EndUserKSP.EU_KSP_SIGN_CONTAINER_ASIC_E			= 5;

EndUserKSP.EU_KSP_SIGN_FORMAT_UNKNOWN			= 0;
EndUserKSP.EU_KSP_SIGN_FORMAT_CADES				= 1;
EndUserKSP.EU_KSP_SIGN_FORMAT_XADES				= 2;
EndUserKSP.EU_KSP_SIGN_FORMAT_PADES				= 3;

EndUserKSP.ERROR_MAP = [];
EndUserKSP.ERROR_MAP[EndUserKSP.EU_KSP_STATUS_REQUEST_OK]				= 
	EU_ERROR_NONE;
EndUserKSP.ERROR_MAP[EndUserKSP.EU_KSP_STATUS_WRONG_PARAM]				= 
	EU_ERROR_BAD_PARAMETER;
EndUserKSP.ERROR_MAP[EndUserKSP.EU_KSP_STATUS_EXPIRED_TRANSACTION]		= 
	EU_ERROR_TRANSMIT_REQUEST;
EndUserKSP.ERROR_MAP[EndUserKSP.EU_KSP_STATUS_USER_CANCEL]				= 
	EU_ERROR_CANCELED_BY_GUI;
EndUserKSP.ERROR_MAP[EndUserKSP.EU_KSP_STATUS_NO_CERT_FOUND]			= 
	EU_ERROR_CERT_NOT_FOUND;
EndUserKSP.ERROR_MAP[EndUserKSP.EU_KSP_STATUS_ERROR_CERTIFICATE]		= 
	EU_ERROR_BAD_CERT;
EndUserKSP.ERROR_MAP[EndUserKSP.EU_KSP_STATUS_OUSTANDING_TRANSACTION]	= 
	EU_ERROR_TRANSMIT_REQUEST;
EndUserKSP.ERROR_MAP[EndUserKSP.EU_KSP_STATUS_INTERNAL_ERROR]			= 
	EU_ERROR_UNKNOWN;

//===============================================================================

EndUserKSP.prototype.MakeError = function(errorCode, kspStatus) {
	var pThis = this;

	if ((kspStatus != null) && 
			(EndUserKSP.ERROR_MAP.indexOf(kspStatus.code) != -1)) {
		errorCode = EndUserKSP.ERROR_MAP.statusesMap[kspStatus.code];
	}

	var error = pThis.m_euSign.MakeError(errorCode);
	if (kspStatus != null) {
		var errorMessage = error.GetMessage() + '. ' + kspStatus.message;
		error = new EUSignCPException(errorCode, errorMessage);
	}

	return error;
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype._StrToDate = function(dateStr) {
	try {
		// "YYYY-MM-DD HH:MM:SS"
		var arr = dateStr.split(' ');
		var dateArr = arr[0].split('-');
		var timeArr = arr[1].split(':');

		var yyyy = parseInt(dateArr[0]);
		var MM = parseInt(dateArr[1]) - 1;
		var dd = parseInt(dateArr[2]);
		if (dd < 0 || dd > 31 ||
			MM < 0 || MM > 12 || yyyy < 0) {
			return null;
		}

		var HH = parseInt(timeArr[0]);
		var mm = parseInt(timeArr[1]);
		var ss = parseInt(timeArr[2]);
		if (HH < 0 || HH > 23 ||
			mm < 0 || mm > 59 ||
			ss < 0 || ss > 59) {
			return null;
		}

		return new Date(yyyy, MM, dd,
			HH, mm, ss, 0);
	} catch (e) {
		return null;
	}
}

//-------------------------------------------------------------------------------

EndUserKSP.prototype._MakeUserId = function() {
	var userId = "";
	if (typeof crypto !== 'undefined') {
		userId = ([1e7]+-1e3+-4e3+-8e3+-1e11).replace(/[018]/g, function(c) {
			return (c ^ crypto.getRandomValues(new Uint8Array(1))[0] & 15 >> c / 4).toString(16);
		});
	} else {
		userId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
			var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
			return v.toString(16);
		});
	}

	return userId;
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.MakeURL = function(url) {
	if (url.indexOf('http://') == 0 ||
		url.indexOf('https://') == 0) {
		return url;
	}

	if ((url.indexOf('/') == 0) && s_origin) {
		return s_origin + url;
	}

	if (s_origin && s_pathname) {
		return s_origin + 
			s_pathname.substr(0, s_pathname.lastIndexOf('/')) + 
			'/' + url;
	}

	return url;
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype._GetKSPSettings = function(kspOrKSPName) {
	var pThis = this;
	var i;

	if (typeof kspOrKSPName == 'string') {
		for (i = 0; i < pThis.m_KSPs.length; i++) {
			if (pThis.m_KSPs[i].name == kspOrKSPName)
				return pThis.m_KSPs[i];
		}
	
		return null;
	} else if (typeof kspOrKSPName == 'number') {
		if (kspOrKSPName == EndUserKSP.EU_KSP_KYIVSTAR ||
			kspOrKSPName == EndUserKSP.EU_KSP_VODAFONE || 
			kspOrKSPName == EndUserKSP.EU_KSP_LIFECELL) {
			return {
				name: 'MobileID',
				ksp: kspOrKSPName
			};
		}

		for (i = 0; i < pThis.m_KSPs.length; i++) {
			if (pThis.m_KSPs[i].ksp == kspOrKSPName)
				return pThis.m_KSPs[i];
		}
	
		return null;
	} else {
		return null;
	}
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype._GetPollingInterval = function(kspSettings) {
	return (kspSettings && 
		typeof kspSettings.pollingInterval == 'number') ? 
		(kspSettings.pollingInterval * 1000) : 
		EndUserKSP.EU_KSP_COMMAND_POLLING_INTERVAL * 1000;
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype._MakeExpireDate = function(expireTime) {
	if (!expireTime)
		expireTime = EndUserKSP.EU_KSP_COMMAND_EXPIRE_TIME;
	var expireDate = new Date();
	expireDate.setTime(expireDate.getTime() + expireTime * 1000);
	return expireDate;
};


//-------------------------------------------------------------------------------

EndUserKSP.prototype._MakeConfirmationURL = function(
	kspSettings, operationType, userId, operationId) {
	var action = (operationType == 
		EndUserKSP.EU_KSP_OPERATION_TYPE_READ_PK) ? 
		'auth' : 'sign';

	return kspSettings.confirmationURL + 
		'?hash=rd/kep/' + 
		'{' + 
			'"clientId":"' + userId + '",' + 
			'"operationId":"' + operationId + '",' + 
			'"action":"' + action + '"' + 
		'}';
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype._SendConfirmationOperationEvent = function(
	kspSettings, confirmationURL, expireDate) {
	var pThis = this;
	var mobileAppName = kspSettings.mobileAppName;
	var qrCode = pThis.m_euSign.QRCodeEncode(
		StringToArray(confirmationURL),
		SS_SERVER_QR_CODE_SCALE);
	qrCode = pThis.m_euSign.Base64Encode(qrCode);

	var event = {
		"type": EndUserEventType.ConfirmKSPOperation,
		"url": confirmationURL,
		"qrCode": qrCode,
		"mobileAppName": mobileAppName,
		"expireDate" : expireDate
	};

	pThis.m_onEvent(event);
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype._SendRequest = function(
	url, request, onSuccess, onError) {
	var pThis = this;

	try {
		var httpRequest = new XMLHttpRequest();
		httpRequest.onload = function() {
			if (httpRequest.readyState != 4)
				return;

			var error;

			if (httpRequest.status != 200) {
				error = pThis.MakeError(
					EU_ERROR_TRANSMIT_REQUEST, null);
				onError(error);
				return;
			}

			var response = null;
			try {
				response = JSON.parse(httpRequest.responseText);
			} catch (e) {
				response = null;
			}

			if (!response) {
				error = pThis.MakeError(
					EU_ERROR_TRANSMIT_REQUEST, null);
				onError(error);
				return;
			}

			onSuccess(response);
		};

		httpRequest.onerror = function(e) {
			var error = pThis.MakeError(
				EU_ERROR_TRANSMIT_REQUEST, null);
			onError(error);
		};

		httpRequest.open("POST", url);
		httpRequest.setRequestHeader("Content-Type", "application/json");
		httpRequest.send(request);
	} catch (e) {
		var error = pThis.MakeError(
			EU_ERROR_TRANSMIT_REQUEST, null);
		onError(error);
	}
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype._SendKSPRequest = function(
	kspSettings, command, parameters, expireDate, 
	onSign, onSuccess, onError) {
	var pThis = this;

	if ((new Date()) > expireDate) {
		onError(pThis.MakeError(
			EU_ERROR_TRANSMIT_REQUEST, null));
		return;
	}

	if (!pThis.m_activeOperation) {
		onError(pThis.MakeError(
			EU_ERROR_CANCELED_BY_GUI, null));
		return;
	}

	var kspURL = pThis.MakeURL(
		command == EndUserKSP.EU_KSP_COMMAND_INITIALIZE_USER_REGISTRATION ||
		command == EndUserKSP.EU_KSP_COMMAND_GET_USER_REGISTRATION_RESULT ? 
		kspSettings.registrationURL : kspSettings.address || pThis.m_url);
	var pollingInterval = pThis._GetPollingInterval(kspSettings);
	
	var request = new EndUserKSPRequest(command, parameters);
	request = JSON.stringify(request);

	pThis._SendRequest(
		kspURL, request, 
		function(response) {
			var error;

			if (!response.data) {
				if (response.error.code != 
						EndUserKSP.EU_KSP_STATUS_OUSTANDING_TRANSACTION) {
					error = pThis.MakeError(
						EU_ERROR_TRANSMIT_REQUEST, response.error);
					onError(error);
					return;
				}

				setTimeout(function() {
					pThis._SendKSPRequest(
						kspSettings, command, parameters,
						expireDate, onSign, onSuccess, onError);
				}, pollingInterval);

				return;
			}

			if ((command == EndUserKSP.EU_KSP_COMMAND_INITIALIZE_READ_PKEY) ||
				(command == EndUserKSP.EU_KSP_COMMAND_INITIALIZE_SIGN_HASH) || 
				(command == EndUserKSP.EU_KSP_COMMAND_INITIALIZE_SIGN_HASHES) ||
				(command == EndUserKSP.EU_KSP_COMMAND_INITIALIZE_USER_REGISTRATION)) {
				if (!response.data.transactionId) {
					error = pThis.MakeError(
						EU_ERROR_TRANSMIT_REQUEST, null);
					onError(error);
					return;
				}
				
				parameters = {
					"ksp": kspSettings.ksp,
					"transactionId": response.data.transactionId
				};

				switch (command) {
				case EndUserKSP.EU_KSP_COMMAND_INITIALIZE_READ_PKEY:
					command = EndUserKSP.EU_KSP_COMMAND_GET_READ_PKEY_RESULT;
					break;
				case EndUserKSP.EU_KSP_COMMAND_INITIALIZE_SIGN_HASH:
					command = EndUserKSP.EU_KSP_COMMAND_GET_SIGN_HASH_RESULT;
					break;
				case EndUserKSP.EU_KSP_COMMAND_INITIALIZE_SIGN_HASHES:
					command = EndUserKSP.EU_KSP_COMMAND_GET_SIGN_HASHES_RESULT;
					break;
				case EndUserKSP.EU_KSP_COMMAND_INITIALIZE_USER_REGISTRATION:
					command = EndUserKSP.EU_KSP_COMMAND_GET_USER_REGISTRATION_RESULT;

					try {
						parameters['signature'] = 
							onSign(response.data.transactionId);
					} catch (e) {
						onError(e);
						return;
					}

					break;
				}

				if (kspSettings.ksp == EndUserKSP.EU_KSP_DIIA) {
					try {
						expireDate = pThis._MakeExpireDate(
							response.data.expireTime);
						
						pThis._SendConfirmationOperationEvent(kspSettings, 
							response.data.confirmationURL, expireDate);
					} catch (e) {
						onError(e);
						return;
					}
				} else {
					expireDate = pThis._MakeExpireDate(
						EndUserKSP.EU_KSP_COMMAND_EXPIRE_TIME);
				}

				setTimeout(function() {
					pThis._SendKSPRequest(
						kspSettings, command, parameters,
						expireDate, onSign, onSuccess, onError);
				}, pollingInterval);

				return;
			}

			onSuccess(response.data);
		}, onError);
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype._MakeKSPKeyContext = function(
	kspSettings, userId, keyId, certificates) {
	var pThis = this;
	var signAlgos = [];
	var euCertificates = [];
	var ownerInfo = new EndUserOwnerInfo(null);

	for (var i = 0; i < certificates.length; i++) {
		var certificate = certificates[i];
		if ((typeof certificate) == 'string')
			certificate = pThis.m_euSign.Base64Decode(certificate);
		var infoEx = pThis.m_euSign.ParseCertificateEx(certificate);
		if ((infoEx.GetKeyUsageType() & 
				(EU_KEY_USAGE_DIGITAL_SIGNATURE | 
					EU_KEY_USAGE_NON_REPUDATION)) != 0) {
			switch (infoEx.GetPublicKeyType()) {
				case EU_CERT_KEY_TYPE_DSTU4145:
					signAlgos.push(EU_CTX_SIGN_DSTU4145_WITH_GOST34311);
					break;
				case EU_CERT_KEY_TYPE_RSA:
					signAlgos.push(EU_CTX_SIGN_RSA_WITH_SHA);
					break;
				case EU_CERT_KEY_TYPE_ECDSA:
					signAlgos.push(EU_CTX_SIGN_ECDSA_WITH_SHA);
					break;
			}
		}

		var euCertificate = new EndUserCertificate(infoEx, certificate);
		euCertificates.push(euCertificate.GetTransferableObject());
		if (i == 0) {
			ownerInfo.SetTransferableObject(
				infoEx.GetTransferableObject());
		}
	}

	return new EndUserKSPKey(
		kspSettings, userId, keyId, signAlgos,
		ownerInfo.GetIssuerCN(), euCertificates, ownerInfo);
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype._SServerGeneratePrivateKey = function(
	keyContext, uaKeysType, uaDSKeysSpec, useDSKeyAsKEP, uaKEPKeysSpec,
	intKeysType, intKeysSpec, operationDescription,
	onSuccess, onError) {
	var pThis = this;

	var kspSettings = keyContext.kspSettings;
	if (!kspSettings || !kspSettings.address/* || !kspSettings.port*/) {
		setTimeout(function() {
			var error = pThis.MakeError(
				EU_ERROR_BAD_PARAMETER, null);
			onError(error);
		}, 1);
		return;
	}

	var uaAlgorithmName = null;
	switch (uaKeysType) {
		case EU_CERT_KEY_TYPE_DSTU4145:
			uaAlgorithmName = "DSTU4145";
		break;
	}

	var uaDSKeyLength = 0;
	switch (uaDSKeysSpec) {
		case EU_KEYS_LENGTH_DS_UA_191:
			uaDSKeyLength = 191;
		break;

		case EU_KEYS_LENGTH_DS_UA_257:
			uaDSKeyLength = 257;
		break;

		case EU_KEYS_LENGTH_DS_UA_307:
			uaDSKeyLength = 307;
		break;
	}

	var uaKEPKeyLength = 0;
	switch (uaKEPKeysSpec) {
		case EU_KEYS_LENGTH_KEP_UA_257:
			uaKEPKeyLength = 257;
			break;

		case EU_KEYS_LENGTH_KEP_UA_431:
			uaKEPKeyLength = 431;
			break;

		case EU_KEYS_LENGTH_KEP_UA_571:
			uaKEPKeyLength = 571;
			break;
		}

	var intAlgorithmName = null;
	switch (intKeysType) {
		case EU_CERT_KEY_TYPE_RSA:
			intAlgorithmName = "RSA";
			break;
	}

	var intKeyLength = 0;
	switch (intKeysSpec) {
		case EU_KEYS_LENGTH_DS_RSA_1024:
			intKeyLength = 1024;
		break;

		case EU_KEYS_LENGTH_DS_RSA_2048:
			intKeyLength = 2048;
		break;

		case EU_KEYS_LENGTH_DS_RSA_3072:
			intKeyLength = 3072;
		break;

		case EU_KEYS_LENGTH_DS_RSA_4096:
			intKeyLength = 4096;
		break;
	}

	var originatorDescription = 
		SS_SERVER_ORIGINATOR_DESCRIPTION.replace("%s", 
		kspSettings.systemId || s_origin);
	if (operationDescription == null) {
		operationDescription = 
			SS_SERVER_GEN_KEY_DESCRIPTION.replace("%s", 
				kspSettings.systemId || s_origin);
	}
	var operationId = null;
	var pollingInterval = pThis._GetPollingInterval(kspSettings);

	try {
		operationId = pThis.m_euSign.SServerClientGeneratePrivateKeyAsync(
			kspSettings.address,
			kspSettings.port,
			keyContext.userId,
			originatorDescription,
			operationDescription,
			uaAlgorithmName, uaDSKeyLength,
			useDSKeyAsKEP, uaKEPKeyLength,
			intAlgorithmName, intKeyLength);
	} catch(e) {
		onError(e);
		return;
	}

	var expireDate = pThis._MakeExpireDate(
		EndUserKSP.EU_KSP_COMMAND_EXPIRE_TIME);
	if (kspSettings.confirmationURL) {
		try {
			var confirmationURL = pThis._MakeConfirmationURL(
				kspSettings, operationType, 
				keyContext.userId, operationId);
			pThis._SendConfirmationOperationEvent(
				kspSettings,
				confirmationURL,
				expireDate);
		} catch (e) {
			onError(e);
			return;
		}
	}
		
	var _getResult = function(expireDate) {
		if ((new Date()) > expireDate) {
			onError(pThis.MakeError(
				EU_ERROR_TRANSMIT_REQUEST, null));
			return;
		}

		if (!pThis.m_activeOperation) {
			onError(pThis.MakeError(
				EU_ERROR_CANCELED_BY_GUI, null));
			return;
		}

		try {
			var key = pThis.m_euSign.SServerClientCheckGeneratePrivateKeyStatus(
				kspSettings.address,
				kspSettings.port,
				keyContext.userId,
				operationId,
				true);

			if (key == null) {
				setTimeout(function() {
					_getResult(expireDate);
				}, pollingInterval);
				return;
			}

			onSuccess(key);
		} catch (e) {
			onError(e);
		}
	};

	setTimeout(function() {
		_getResult(expireDate);
	}, pollingInterval);
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype._SServerSignHashes = function(
	keyContext, signAlgo, hashes, operationType, operationDescription,
	onSuccess, onError) {
	var pThis = this;

	var kspSettings = keyContext.kspSettings;
	if (!kspSettings || !kspSettings.address/* || !kspSettings.port*/) {
		setTimeout(function() {
			var error = pThis.MakeError(
				EU_ERROR_BAD_PARAMETER, null);
			onError(error);
		}, 1);
		return;
	}

	var signAlgoName = '';
	switch (signAlgo) {
		case EU_CTX_SIGN_DSTU4145_WITH_GOST34311:
			signAlgoName = "DSTU4145";
			break;
		case EU_CTX_SIGN_RSA_WITH_SHA:
			signAlgoName = "RSA";
			break;
	}

	var originatorDescription = 
		SS_SERVER_ORIGINATOR_DESCRIPTION.replace("%s", 
		kspSettings.systemId || s_origin);
	var hashesDescriptions = [];
	var hashesValues = [];
	var operationId = null;
	var pollingInterval = pThis._GetPollingInterval(kspSettings);

	for (var i = 0; i < hashes.length; i++) {
		var item = hashes[i];
		hashesDescriptions.push(item.name);
		hashesValues.push(item.val);
	}
	
	if (kspSettings.ksp == EndUserKSP.EU_KSP_PB) { 
		try {
			operationId = pThis.m_euSign.SServerClientSignHashesAsync(
				kspSettings.address,
				kspSettings.port,
				keyContext.userId,
				originatorDescription,
				operationDescription,
				hashesDescriptions,
				hashesValues,
				signAlgoName);
		} catch(e) {
			onError(e);
			return;
		}

		var expireDate = pThis._MakeExpireDate(
			EndUserKSP.EU_KSP_COMMAND_EXPIRE_TIME);
		if (kspSettings.confirmationURL) {
			try {
				var confirmationURL = pThis._MakeConfirmationURL(
					kspSettings, operationType, 
					keyContext.userId, operationId);
				pThis._SendConfirmationOperationEvent(
					kspSettings,
					confirmationURL,
					expireDate);
			} catch (e) {
				onError(e);
				return;	
			}
		}

		var _getResult = function(expireDate) {
			if ((new Date()) > expireDate) {
				onError(pThis.MakeError(
					EU_ERROR_TRANSMIT_REQUEST, null));
				return;
			}

			if (!pThis.m_activeOperation) {
				onError(pThis.MakeError(
					EU_ERROR_CANCELED_BY_GUI, null));
				return;
			}
	
			try {
				var signatures = [];
				var results = pThis.m_euSign.SServerClientCheckSignHashesStatus(
					kspSettings.address,
					kspSettings.port,
					keyContext.userId,
					operationId);
				if (results.length > 0) {
					hashesValues.forEach(function(hash) {
						var result = null;
						for (var i = 0; i < results.length; i++) {
							if (hash == results[i].GetHash()) {
								result = results[i];
								break;
							}
						}
	
						if (result == null)
							throw pThis.MakeError(EU_ERROR_TRANSMIT_REQUEST);
	
						if (result.GetError() != EU_ERROR_NONE) {
							throw pThis.MakeError(
								result.GetError(), result.GetStatus());
						}
	
						signatures.push(result.GetSignature());
					});
				}
	
				if (signatures.length == 0) {
					setTimeout(function() {
						_getResult(expireDate);
					}, pollingInterval);
					return;
				}
	
				onSuccess(signatures);
			} catch (e) {
				onError(e);
			}
		};
	
		setTimeout(function() {
			_getResult(expireDate);
		}, pollingInterval);
	} else {
		var signatures = [];

		var _sendKSPRequest = function(index) {
			if (index >= hashesValues.length) {
				onSuccess(signatures);
				return;
			}
	
			try {
				operationId = pThis.m_euSign.SServerClientSignHashAsync(
					kspSettings.address,
					kspSettings.port,
					keyContext.userId,
					originatorDescription,
					operationDescription,
					hashesValues[index],
					signAlgoName);
			} catch(e) {
				onError(e);
				return;
			}

			var expireDate = pThis._MakeExpireDate(
				EndUserKSP.EU_KSP_COMMAND_EXPIRE_TIME);
			if (kspSettings.confirmationURL) {
				try {
					var confirmationURL = pThis._MakeConfirmationURL(
						kspSettings, operationType, 
						keyContext.userId, operationId);
					pThis._SendConfirmationOperationEvent(
						kspSettings,
						confirmationURL,
						expireDate);
				} catch (e) {
					onError(e);
					return;	
				}
			}
				
			var _getResult = function(expireDate) {
				if ((new Date()) > expireDate) {
					onError(pThis.MakeError(
						EU_ERROR_TRANSMIT_REQUEST, null));
					return;
				}
		
				if (!pThis.m_activeOperation) {
					onError(pThis.MakeError(
						EU_ERROR_CANCELED_BY_GUI, null));
					return;
				}

				try {
					var sign = pThis.m_euSign.SServerClientCheckSignHashStatus(
						kspSettings.address,
						kspSettings.port,
						keyContext.userId,
						operationId,
						true);
		
					if (sign == null) {
						setTimeout(function() {
							_getResult(expireDate);
						}, pollingInterval);
						return;
					}
		
					signatures.push(sign);
					_sendKSPRequest(index + 1);
				} catch (e) {
					onError(e);
				}
			};
		
			setTimeout(function() {
				_getResult(expireDate);
			}, pollingInterval);
		};
	
		_sendKSPRequest(0);
	}
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype._CtxReadPrivateKeyWithServer = function(
	kspSettings, userId, getCerts, keyId, preAuth, 
	onSuccess, onError) {
	var pThis = this;

	if (preAuth) {
		var params = {
			"ksp": kspSettings.ksp,
			"userId": userId,
			"keyId": keyId
		};
		var expireDate = pThis._MakeExpireDate(
			EndUserKSP.EU_KSP_COMMAND_EXPIRE_TIME);

		pThis.m_activeOperation = true;

		pThis._SendKSPRequest(
			kspSettings, EndUserKSP.EU_KSP_COMMAND_INITIALIZE_READ_PKEY, 
			params, expireDate, null,
			function(data) {
				pThis.m_activeOperation = false;

				if (!data) {
					var error = pThis.MakeError(
						EU_ERROR_TRANSMIT_REQUEST, null);
					onError(error);
					return;
				}
	
				pThis._CtxReadPrivateKeyWithServer(
					kspSettings, userId, getCerts, keyId, false, 
					onSuccess, onError);
			}, 
			function(error) {
				pThis.m_activeOperation = false;

				onError(error);
			});

		return;
	}

	var signAlgos = [];
	var certIssuerCN = null;

	switch (kspSettings.ksp) {
		case EndUserKSP.EU_KSP_KYIVSTAR:
			signAlgos = [EU_CTX_SIGN_ECDSA_WITH_SHA, 
				EU_CTX_SIGN_RSA_WITH_SHA];
			certIssuerCN = EndUserKSP.EU_KSP_CERT_ISSUER_CN_KYIVSTAR;
			break;

		case EndUserKSP.EU_KSP_VODAFONE:
		case EndUserKSP.EU_KSP_LIFECELL:
			signAlgos = [EU_CTX_SIGN_DSTU4145_WITH_GOST34311];
			certIssuerCN = (kspSettings.ksp == 
					EndUserKSP.EU_KSP_VODAFONE) ? 
				EndUserKSP.EU_KSP_CERT_ISSUER_CN_VODAFONE : 
				EndUserKSP.EU_KSP_CERT_ISSUER_CN_LIFECELL;
			break;

		case EndUserKSP.EU_KSP_IIT:
			signAlgos = [EU_CTX_SIGN_DSTU4145_WITH_GOST34311];
			userId =  (typeof kspSettings.clientIdType === 'undefined' || 
				kspSettings.clientIdType == 0) ? 
				userId.toUpperCase() : userId;
			break;

		case EndUserKSP.EU_KSP_PB:
			if (!userId)
				userId = pThis._MakeUserId();
			userId = kspSettings.clientIdPrefix + userId;
			signAlgos = [EU_CTX_SIGN_DSTU4145_WITH_GOST34311];
			break;

		case EndUserKSP.EU_KSP_UKEY:
			signAlgos = [EU_CTX_SIGN_DSTU4145_WITH_GOST34311];
			break;

		case EndUserKSP.EU_KSP_DIIA:
			signAlgos = keyId == EU_CTX_SIGN_ECDSA_WITH_SHA ? 
				[EU_CTX_SIGN_ECDSA_WITH_SHA] : 
				[EU_CTX_SIGN_DSTU4145_WITH_GOST34311];
			break;

		default:
			setTimeout(function() {
				var error = pThis.MakeError(
					EU_ERROR_BAD_PARAMETER, null);
				onError(error);
			}, 1);
			return;
	}

	var keyContext = new EndUserKSPKey(
		kspSettings, userId, keyId, signAlgos,
		certIssuerCN, [], null);
	if (!getCerts) {
		setTimeout(function() {
			onSuccess(keyContext);
		}, 1);
		return;
	}

	var hashes = [
		{
			name: "Зчитування ос. ключа",
			val: "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA="
		}
	];
	var signAlgo = signAlgos[0];
	var operationDescription = 
		SS_SERVER_READ_KEY_DESCRIPTION.replace("%s", 
		kspSettings.systemId || s_origin);
	var operationType = EndUserKSP.EU_KSP_OPERATION_TYPE_READ_PK;

	pThis._CtxSignHashesWithServer(keyContext,
		EndUserKSP.EU_KSP_SIGN_CONTAINER_CADES,
		EndUserKSP.EU_KSP_SIGN_FORMAT_CADES,
		signAlgo, hashes, operationType, operationDescription,
		function(signatures) {
			try {
				var signedData = pThis.m_euSign.Base64Decode(signatures[0]);
				var signerInfo = pThis.m_euSign.CtxGetSignerInfo(
					pThis.m_context, 0, signedData);
				var keyContext = pThis._MakeKSPKeyContext(
					kspSettings, userId, keyId, [signerInfo.GetData()]);

				onSuccess(keyContext);
			} catch (e) {
				pThis.ResetPrivateKey();

				onError(e);
				return;
			}
		},
		function(e) {
			pThis.ResetPrivateKey();

			onError(e);
		});
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype._CtxSignHashesWithServer = function(
	keyContext, signContainer, signFormat, signAlgo, 
	hashes, operationType, operationDescription,
	onSuccess, onError) {
	var pThis = this;

	if (keyContext == null) {
		setTimeout(function() {
			var error = pThis.MakeError(
				EU_ERROR_BAD_CERT, null);
			onError(error);
		}, 1);
		return;
	}

	var kspSettings = keyContext.kspSettings;
	if (!kspSettings) {
		setTimeout(function() {
			var error = pThis.MakeError(
				EU_ERROR_BAD_PARAMETER, null);
			onError(error);
		}, 1);
		return;
	}

	if (keyContext.signAlgos.indexOf(signAlgo) == -1) {
		setTimeout(function() {
			var error = pThis.MakeError(
				EU_ERROR_PKI_FORMATS_FAILED, null);
			onError(error);
		}, 1);
		return;
	}

	if (signContainer == EndUserKSP.EU_KSP_SIGN_CONTAINER_PADES &&
		kspSettings.ksp != EndUserKSP.EU_KSP_DIIA) {
		setTimeout(function() {
			var error = pThis.MakeError(
				EU_ERROR_NOT_SUPPORTED, null);
			onError(error);
		}, 1);
		return;
	}

	if (operationDescription == null) {
		operationDescription = 
			SS_SERVER_SIGN_HASH_DESCRIPTION.replace("%s", 
			kspSettings.systemId || s_origin);
	}

	var expireDate = pThis._MakeExpireDate(
		EndUserKSP.EU_KSP_COMMAND_EXPIRE_TIME);	
	pThis.m_activeOperation = true;

	if (kspSettings.ksp == EndUserKSP.EU_KSP_IIT ||
		kspSettings.ksp == EndUserKSP.EU_KSP_PB) {
		pThis._SServerSignHashes(
			keyContext, signAlgo, hashes, 
			operationType, operationDescription,
			onSuccess, 
			function(error) {
				pThis.m_activeOperation = false;

				onError(error);
			});
		return;
	}

	if (kspSettings.ksp == EndUserKSP.EU_KSP_DIIA) {
		var signType = (signContainer == 
			EndUserKSP.EU_KSP_SIGN_CONTAINER_PADES) &&
			(pThis.m_signType > EU_SIGN_TYPE_CADES_T) ?
				EU_SIGN_TYPE_CADES_T : pThis.m_signType;
		var params = {
			"ksp": kspSettings.ksp,
			"signContainer": signContainer,
			"signFormat": signFormat,
			"signAlgo": signAlgo,
			"signType": signType,
			"hashes": hashes,
			"systemId": kspSettings.systemId || s_origin
		};

		pThis._SendKSPRequest(
			kspSettings,
			EndUserKSP.EU_KSP_COMMAND_INITIALIZE_SIGN_HASHES, params,
			expireDate, null,
			function(data) {
				pThis.m_activeOperation = false;

				if (!data || !data.signatures) {
					var error = pThis.MakeError(
						EU_ERROR_TRANSMIT_REQUEST, null);
					onError(error);
					return;
				}
	
				onSuccess(data.signatures);
			},
			function(error) {
				pThis.m_activeOperation = false;

				onError(error);
			});
	} else {
		/* !!!! */
		/* Remove this when MobileID is disabled */
		var signatures = [];
		var _sendKSPRequest = function(index) {
			if (index >= hashes.length) {
				pThis.m_activeOperation = false;

				onSuccess(signatures);
				return;
			}
	
			var params = {
				"ksp": kspSettings.ksp,
				"userId": keyContext.userId,
				"keyId": keyContext.keyId,
				"hash": hashes[index].val,
				"signAlgo": signAlgo,
				"signType": pThis.m_signType,
			};
		
			pThis._SendKSPRequest(
				kspSettings,
				EndUserKSP.EU_KSP_COMMAND_INITIALIZE_SIGN_HASH, params, 
				expireDate, null,
				function(data) {
					if (!data || !data.signature) {
						pThis.m_activeOperation = false;

						var error = pThis.MakeError(
							EU_ERROR_TRANSMIT_REQUEST, null);
						onError(error);
						return;
					}
		
					signatures.push(data.signature);
					_sendKSPRequest(index + 1);
				},
				function(error) {
					pThis.m_activeOperation = false;

					onError(error);
				});
		};
	
		_sendKSPRequest(0);
		/* !!!! */
	}
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype._GetHashAlgo = function(signAlgo) {
	switch (signAlgo) {
		case EU_CTX_SIGN_DSTU4145_WITH_GOST34311:
			return EU_CTX_HASH_ALGO_GOST34311;

		case EU_CTX_SIGN_RSA_WITH_SHA:
		case EU_CTX_SIGN_ECDSA_WITH_SHA:
			return EU_CTX_HASH_ALGO_SHA256;

		default:
			this.m_euSign.RaiseError(EU_ERROR_BAD_PARAMETER);
			break;
	}
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype._SignHashOrData = function(
	signContainer, signFormat,
	signAlgo, data, hash, external, appendCert, previousSign, 
	asBase64String, onSuccess, onError) {
	try {
		var pThis = this;
		var datas = DataToNamedDataArray(data);
		var hashes = DataToNamedDataArray(hash);
		var previousSigns = DataToNamedDataArray(previousSign);

		if (data != null || (previousSign != null && !external)) {
			var hashAlgo = pThis._GetHashAlgo(signAlgo);
			var datasToHash = (data != null) ? datas : previousSigns;
			var datasHashes = []; 

			for (var i = 0; i < datasToHash.length; i++) {
				var dataToHash = (data != null) ? 
					datasToHash[i].val : 
					pThis.m_euSign.GetDataFromSignedData(datasToHash[i].val);
				var dataHash = pThis.m_euSign.CtxHashData(
					pThis.m_context, hashAlgo, null, dataToHash, true);
				datasHashes.push(dataHash);
			}

			hashes = DataToResult(datasToHash, datasHashes);
		}

		hashes = hashes.map(function(item) {
			var val = (typeof item.val != 'string') ? 
				pThis.m_euSign.Base64Encode(item.val) : item.val;
			return {name: item.name, val: val};
		});

		pThis._CtxSignHashesWithServer(pThis.m_keyContext,
			signContainer, signFormat, signAlgo, hashes, 
			EndUserKSP.EU_KSP_OPERATION_TYPE_SIGN_HASH, null,
			function(signs) {
				pThis._AppendValidationDataToSign(
					signContainer, signFormat, 
					external ? [] : datas, signs, previousSigns,
					appendCert, asBase64String, 
					function(signs) {
						var result = DataToResult((hash != null) ? 
							hash : ((data != null) ? 
								data : previousSign), 
							signs);
						onSuccess(result);
					}, onError);
			}, 
			onError);	
	} catch (e) {
		setTimeout(function() {
			onError(e);
		}, 1);
		return;
	}
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype._AppendValidationDataToSign = function(
	signContainer, signFormat,
	datas, signs, previousSigns, appendCert, asBase64String, 
	onSuccess, onError) {
	var pThis = this;
	var euSign = pThis.m_euSign;

	if (signContainer == EndUserKSP.EU_KSP_SIGN_CONTAINER_PADES) {
		setTimeout(function() {
			onSuccess(signs);
		}, 1);
		return;
	}

	try {
		var signedDatas = [];

		for (var i = 0; i < signs.length; i++) {
			var signedData = euSign.Base64Decode(signs[i]);
			var signerInfo = euSign.CtxGetSignerInfo(
				pThis.m_context, 0, signedData);
			var signerCert = signerInfo.GetData();
			var previousSign = null;

			if (previousSigns.length == 0) {
				previousSign = euSign.CreateEmptySign(
					datas.length == 0 ? null : datas[i].val);
			}
			else {
				previousSign = previousSigns[i].val; 
			}

			var signer = euSign.GetSigner(0, signedData);
			signer = euSign.AppendValidationDataToSigner(
				signer, signerCert);
			signedData = euSign.AppendSigner(
				signer, appendCert ? signerCert : null, 
				previousSign, asBase64String);

			signedDatas.push(signedData);
		}

		setTimeout(function() {
			onSuccess(signedDatas);
		}, 1);
	} catch (e) {
		setTimeout(function(){
			onError(e);
		}, 1);
	}
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype._ASiCAppendSign = function(
	signAlgo, asicType, signType, signLevel, referencesNames, asicData,
	asBase64String, onSuccess, onError) {
	try {
		var pThis = this;
		var previousASiCData = DataToNamedDataArray(asicData);

		if (asicType == EU_ASIC_TYPE_UNKNOWN) {
			asicType = pThis.m_euSign.ASiCGetASiCType(
				previousASiCData[0].val);
		}

		if (signType == EU_ASIC_SIGN_TYPE_UNKNOWN) {
			signType = pThis.m_euSign.ASiCGetSignType(
				previousASiCData[0].val);
		}

		var asicSigner = pThis.m_euSign.ASiCCreateSignerBegin(
			signAlgo, asicType, signType, referencesNames, 
			previousASiCData[0].val);
		var itemToSign = {
			name: previousASiCData[0].name,
			val: asicSigner.GetAttrsHash()
		};
	
		var signContainer = EndUserKSP.EU_KSP_SIGN_CONTAINER_UNKNOWN;
		switch (asicType)
		{
			case EU_ASIC_TYPE_S:
				signContainer = EndUserKSP.EU_KSP_SIGN_CONTAINER_ASIC_S;
			break;

			case EU_ASIC_TYPE_E:
				signContainer = EndUserKSP.EU_KSP_SIGN_CONTAINER_ASIC_E;
			break;
		}

		var signFormat = EndUserKSP.EU_KSP_SIGN_FORMAT_UNKNOWN;
		switch (signType)
		{
			case EU_ASIC_SIGN_TYPE_CADES:
				signFormat = EndUserKSP.EU_KSP_SIGN_FORMAT_CADES;
			break;

			case EU_ASIC_SIGN_TYPE_XADES:
				signFormat = EndUserKSP.EU_KSP_SIGN_FORMAT_XADES;
			break;
		}

		pThis._SignHashOrData(
			signContainer, signFormat,
			signAlgo, null, itemToSign, 
			true, true, null, false, function(signature) {
				try {
					asicData = pThis.m_euSign.ASiCCreateSignerEnd(
						asicType, signType, signLevel,
						asicSigner.GetSignatureReference(),
						signature.val, asicSigner.GetASiCData(),
						asBase64String);
				} catch (e) {
					onError(e);
					return;
				}

				var result = {
					name: previousASiCData[0].name,
					val: asicData
				};
				onSuccess(result);
			}, onError);
	} catch (e) {
		setTimeout(function() {
			onError(e);
		}, 1);

		return;
	}
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.SetRuntimeParameter = function(name, value) {
	if (name == EU_SIGN_TYPE_PARAMETER)
		this.m_signType = value;
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.GetKeySupportedSignAlgos = function() {
	return (this.m_keyContext != null) ? 
		this.m_keyContext.signAlgos : [];
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.GetKeyCertIssuerCN = function() {
	return (this.m_keyContext != null) ? 
		this.m_keyContext.certIssuerCN : null;
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.ResetPrivateKey = function() {
	this.m_keyContext = null;
	this.m_activeOperation = false;
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.ResetOperation = function() {
	this.m_activeOperation = false;
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.IsPrivateKeyReaded = function() {
	return this.m_keyContext != null;
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.ReadPrivateKey = function(
	ksp, userId, getCerts, keyId, onSuccess, onError) {
	var pThis = this;
	var kspSettings = pThis._GetKSPSettings(ksp);
	
	if (kspSettings == null) {
		setTimeout(function() {
			var error = pThis.MakeError(
				EU_ERROR_BAD_PARAMETER, null);
			onError(error);
		}, 1);
		return;
	}

	pThis._CtxReadPrivateKeyWithServer(
		kspSettings, userId, getCerts, keyId, 
		(kspSettings.ksp == EndUserKSP.EU_KSP_UKEY), 
		function(keyContext) {
			pThis.m_keyContext = keyContext;
			onSuccess(keyContext.ownerInfo);
		}, onError);
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.GetOwnCertificates = function(
	onSuccess, onError) {
	var pThis = this;

	if (!pThis.IsPrivateKeyReaded()) {
		setTimeout(function() {
			var error = pThis.MakeError(
				EU_ERROR_BAD_CERT, null);
			onError(error);
		}, 1);
		return;
	}

	setTimeout(function() {
		onSuccess(pThis.m_keyContext.certs);
	}, 1);
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.ChangeOwnCertificatesStatus = function(
	requestType, revocationReason, onSuccess, onError) {
	var pThis = this;

	if (!pThis.IsPrivateKeyReaded()) {
		setTimeout(function() {
			var error = pThis.MakeError(
				EU_ERROR_BAD_CERT, null);
			onError(error);
		}, 1);
		return;
	}

	setTimeout(function() {
		var error = pThis.MakeError(
			EU_ERROR_NOT_SUPPORTED, null);
		onError(error);
	}, 1);
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.MakeNewCertificate = function(
	pkContext, uaKeysType, uaDSKeysSpec, useDSKeyAsKEP, uaKEPKeysSpec,
	internationalKeysType, internationalKeysSpec,
	newUserId, newKSP, onSuccess, onError) {
	var pThis = this;
	var kspSettings = pThis._GetKSPSettings(newKSP);
	
	if (kspSettings == null) {
		setTimeout(function() {
			var error = pThis.MakeError(
				EU_ERROR_BAD_PARAMETER, null);
			onError(error);
		}, 1);
		return;
	}

	var keyContext = new EndUserKSPKey(
		kspSettings, newUserId, null, [], null, [], null);
	pThis.m_activeOperation = true;

	pThis._SServerGeneratePrivateKey(keyContext,
		uaKeysType, uaDSKeysSpec, useDSKeyAsKEP, uaKEPKeysSpec,
		internationalKeysType, internationalKeysSpec, 
		null, function(key) {
			pThis.m_activeOperation = false;

			try {
				pThis.m_euSign.CtxMakeNewOwnCertificateWithCR(pkContext, 
					key.GetUARequest(), key.GetUAKEPRequest(), 
					key.GetInternationalRequest(), null);
			} catch (e) {
				onError(e);
				return;
			}

			pThis._CtxReadPrivateKeyWithServer(
				kspSettings, newUserId, true, null, false, 
				function(keyContext) {
					onSuccess(keyContext.certs);
				}, onError);
		},
		function(error) {
			pThis.m_activeOperation = false;

			onError(error);
		});
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.GetClientRegistrationToken = function(
	pkContext, ksp, onSuccess, onError) {
	var pThis = this;
	var kspSettings = pThis._GetKSPSettings(ksp);

	if (!pkContext) {
		setTimeout(function() {
			var error = pThis.MakeError(
				EU_ERROR_BAD_CERT, null);
			onError(error);
		}, 1);
		return;
	}

	if (!kspSettings || !kspSettings.registrationURL) {
		setTimeout(function() {
			var error = pThis.MakeError(
				EU_ERROR_BAD_PARAMETER, null);
			onError(error);
		}, 1);
		return;
	}

	if (!kspSettings ||
		!kspSettings.registrationURL) {
		setTimeout(function() {
			var error = pThis.MakeError(
				EU_ERROR_BAD_PARAMETER, null);
			onError(error);
		}, 1);
		return;
	}

	var params = {
		"ksp": kspSettings.ksp
	};

	var expireDate = pThis._MakeExpireDate(
		EndUserKSP.EU_KSP_COMMAND_EXPIRE_TIME);
	pThis.m_activeOperation = true;

	pThis._SendKSPRequest(
		kspSettings,
		EndUserKSP.EU_KSP_COMMAND_INITIALIZE_USER_REGISTRATION,
		params, expireDate,
		function(data) {
			var signAlgo = EU_CTX_SIGN_DSTU4145_WITH_GOST34311;
			var external = true;
			var appendCert = true;
			var asBase64String = true;

			return pThis.m_euSign.CtxSignData(
				pkContext, signAlgo, data,
				external, appendCert, asBase64String);
		},
		function(data) {
			pThis.m_activeOperation = false;

			if (!data || !data.token) {
				var error = pThis.MakeError(
					EU_ERROR_TRANSMIT_REQUEST, null);
				onError(error);
				return;
			}

			var qrCode = null;

			try {
				qrCode = pThis.m_euSign.QRCodeEncode(
					StringToArray(data.token),
					SS_SERVER_QR_CODE_SCALE);
				qrCode = pThis.m_euSign.Base64Encode(qrCode);
			} catch (error) {
				onError(error);
				return;
			}

			var token = JSON.parse(data.token);

			onSuccess({
				version: token.version,
				type: token.type,
				serverId: token.serverId,
				serverName: token.serverName,
				clientType: token.clientType,
				clientName: token.clientName,
				rawSign: token.rawSign,
				expiration: pThis._StrToDate(token.expiration),
				token: data.token,
				qrCode: qrCode
			});
		},
		function(error) {
			pThis.m_activeOperation = false;

			onError(error);
		});
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.SignHash = function(signAlgo, hash, 
	appendCert, asBase64String, onSuccess, onError) {
	var pThis = this;

	pThis._SignHashOrData(
		EndUserKSP.EU_KSP_SIGN_CONTAINER_CADES,
		EndUserKSP.EU_KSP_SIGN_FORMAT_CADES,
		signAlgo, null, hash, true, 
		appendCert, null, asBase64String, onSuccess, onError);
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.SignDataEx = function(signAlgo, data, 
	external, appendCert, asBase64String, onSuccess, onError) {
	var pThis = this;

	pThis._SignHashOrData(
		EndUserKSP.EU_KSP_SIGN_CONTAINER_CADES,
		EndUserKSP.EU_KSP_SIGN_FORMAT_CADES,
		signAlgo, data, null, external, 
		appendCert, null, asBase64String, onSuccess, onError);
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.AppendSign = function(
	signAlgo, data, previousSign, appendCert, asBase64String,
	onSuccess, onError) {
	var pThis = this;
	
	pThis._SignHashOrData(
		EndUserKSP.EU_KSP_SIGN_CONTAINER_CADES,
		EndUserKSP.EU_KSP_SIGN_FORMAT_CADES,
		signAlgo, data, null, data != null, 
		appendCert, previousSign, asBase64String, onSuccess, onError);
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.AppendSignHash = function(
	signAlgo, hash, previousSign, appendCert, asBase64String,
	onSuccess, onError) {
	var pThis = this;

	pThis._SignHashOrData(
		EndUserKSP.EU_KSP_SIGN_CONTAINER_CADES,
		EndUserKSP.EU_KSP_SIGN_FORMAT_CADES,
		signAlgo, null, hash, true, 
		appendCert, previousSign, asBase64String, onSuccess, onError);
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.EnvelopData = function(
	recipientsCerts, data, signData, appendCert, asBase64String, useDynamicKey, 
	onSuccess, onError) {
	var pThis = this;

	try {
		if (signData || !useDynamicKey) {
			pThis.m_euSign.RaiseError(EU_ERROR_NOT_SUPPORTED);
			return;
		}

		var result = pThis.m_euSign.EnvelopDataToRecipientsWithDynamicKey(
			recipientsCerts, false, appendCert, data, asBase64String);
		setTimeout(function() {
			onSuccess(result);
		}, 1);
	} catch (e) {
		setTimeout(function() {
			onError(e);
		}, 1);

		return;
	}
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.DevelopData = function(
	envelopedData, senderCert, onSuccess, onError) {
	var pThis = this;

	try {
		pThis.m_euSign.RaiseError(EU_ERROR_NOT_SUPPORTED);
	} catch (e) {
		setTimeout(function() {
			onError(e);
		}, 1);

		return;
	}
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.PDFSignData = function(
	signAlgo, pdfData, signType, asBase64String, onSuccess, onError) {
	var pThis = this;

	try {
		var pThis = this;
		var pdfDatas = DataToNamedDataArray(pdfData);
		var pdfSigners = [];
		var itemsToSigns = [];

		for (var i = 0; i < pdfDatas.length; i++) {
			var pdfSigner = pThis.m_euSign.PDFCreateSignerBegin(
				signAlgo, pdfDatas[i].val);

			pdfSigners.push(pdfSigner);
			itemsToSigns.push({
				name: pdfDatas[i].name,
				val: pdfSigner.GetAttrsHash()
			});
		}

		pThis._SignHashOrData(
			EndUserKSP.EU_KSP_SIGN_CONTAINER_PADES, 
			EndUserKSP.EU_KSP_SIGN_FORMAT_PADES,
			signAlgo, null, itemsToSigns, 
			true, true, null, false, function(signatures) {
				var signs = [];
				try {
					for (var i = 0; i < pdfDatas.length; i++) {
						var signedPDF = pThis.m_euSign.PDFCreateSignerEnd(
							pdfSigners[i].GetPDFData(), signType,
							pdfSigners[i].GetSignatureReference(), 
							signatures[i].val, asBase64String);
						signs.push(signedPDF);
					}
				} catch (e) {
					onError(e);
					return;
				}

				var result = DataToResult(pdfData, signs);
				onSuccess(result);
			}, onError);
	} catch (e) {
		setTimeout(function() {
			onError(e);
		}, 1);

		return;
	}
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.ASiCSignData = function(
	signAlgo, asicType, signType, signLevel, references,
	asBase64String, onSuccess, onError) {
	var pThis = this;

	try {
		references = DataToNamedDataArray(references);

		var asicReferences = [];
		var asicReferencesNames = [];
		for (var i = 0; i < references.length; i++) {
			var reference = new EndUserReference(
				references[i].name, references[i].val);
			asicReferences.push(reference);
			asicReferencesNames.push(references[i].name);
		}

		var emptyASiCData = pThis.m_euSign.ASiCCreateEmptySign(
			asicType, signType, asicReferences);
		
		var asicData = {
			name: asicReferences[0].name + 
				(asicType == EU_ASIC_TYPE_S ? 
					'.asics' : '.asice'),
			val: emptyASiCData
		};

		pThis._ASiCAppendSign(
			signAlgo, asicType, signType, signLevel,
			asicReferencesNames, asicData,
			asBase64String, onSuccess, onError);
	} catch (e) {
		setTimeout(function() {
			onError(e);
		}, 1);

		return;
	}
};

//-------------------------------------------------------------------------------

EndUserKSP.prototype.ASiCAppendSign = function(
	signAlgo, signLevel, referencesNames, asicData,
	asBase64String, onSuccess, onError) {
	var pThis = this;

	pThis._ASiCAppendSign(
		signAlgo, EU_ASIC_TYPE_UNKNOWN, EU_ASIC_SIGN_TYPE_UNKNOWN, 
		signLevel, referencesNames, asicData,
		asBase64String, onSuccess, onError);
};

//===============================================================================
;

//===============================================================================

var EU_CMP_COMPATIBILITY_NONE						= 0x00000000;
var EU_CMP_COMPATIBILITY_DOWNLOAD_EU_CERTS			= 0x00000001;
var EU_CMP_COMPATIBILITY_SEARCH_EU_CERTS			= 0x00000002;

var EU_CADES_TYPE_UNKNOWN = 0;
var EU_CADES_TYPE_DETACHED = 1;
var EU_CADES_TYPE_ENVELOPED = 3;

var EU_SIGN_CONTAINER_TYPE_UNKNOWN = 0;
var EU_SIGN_CONTAINER_TYPE_CADES = 1;
var EU_SIGN_CONTAINER_TYPE_XADES = 2;
var EU_SIGN_CONTAINER_TYPE_PADES = 3;
var EU_SIGN_CONTAINER_TYPE_ASIC = 4;

var EndUserEventType = {
	"None": 0,
	"All": 1,
	"ConfirmKSPOperation": 2
};

//===============================================================================

var s_loaded = false;
var s_endUser = null;
var s_origin = '';
var s_pathname = '';

//===============================================================================

function EUSignCPModuleInitialized(loaded) {
	s_loaded = loaded;
	s_endUser = new EndUser();
}

//===============================================================================

self.onmessage = function(msg) {
	if (!s_loaded) {
		setTimeout(function() {
			onmessage(msg);
		}, 50);
		return;
	}

	s_endUser.OnMessage(msg.data);
};

//===============================================================================

var TaxReportPKey = function() {
	this.signPKCtx = null;
	this.signCert = null;
	this.envelopPKCtx = null;
	this.envelopCert = null;
};

//===============================================================================

function DataToNamedDataArray(data) {
	data = (data != null) ? data : [];
	data = !Array.isArray(data) ? [data] : data;
	var namedData = [];

	for (var i = 0; i < data.length; i++) {
		var named = typeof data[i].name !== 'undefined' && 
			typeof data[i].val !== 'undefined';
		namedData.push({
			name: named ? data[i].name : 'Ім\'я відсутнє',
			val: named ? data[i].val : data[i]
		});
	}

	return namedData;
}

function DataToResult(data, dataResult) {
	var results = [];
	var single = !Array.isArray(data);
	var arrData = single ? [data] : data;
	
	for (var i = 0; i < arrData.length; i++) {
		var named = typeof arrData[i].name !== 'undefined' && 
			typeof arrData[i].val !== 'undefined';
		var result = named ? {
			name: arrData[i].name,
			val: dataResult[i]
		} : dataResult[i];
		results.push(result);
	}

	return single ? results[0] : results;
}

//===============================================================================

function GetOptionalParam(param, defaultParam) {
	return typeof param === 'undefined' ? defaultParam : param;
}

//===============================================================================

var EndUser = function() {
	this.m_euSign = EUSignCP();
	this.m_settings = null;
	this.m_initialized = false;
	this.m_context = null;
	this.m_pkContext = null;
	this.m_euKSP = null;
	this.m_eventListeners = [];
};

//-------------------------------------------------------------------------------

EndUser.prototype.OnMessage = function(msg) {
	var pThis = this;

	var resp = {
		id: msg.id,
		cmd: msg.cmd,
		result: null,
		error: null
	};

	var _onSuccess = function(result) {
		resp.result = result;

		postMessage(resp);
	};

	var _onError = function(e) {
		resp.error = pThis.MakeError(e);
		postMessage(resp);
	};

	try {
		s_origin = msg.origin;
		s_pathname = msg.pathname;

		var params = msg.params.concat([_onSuccess, _onError]);
		pThis[msg.cmd].apply(pThis, params);
	} catch (e) {
		_onError(e);
	}
};

//-------------------------------------------------------------------------------

EndUser.prototype.OnEvent = function(event) {
	var listener = this.m_eventListeners[event.type] ||
		this.m_eventListeners[EndUserEventType.All];
	if (listener) {
		var resp = {
			id: -2,
			cmd: null,
			result: event,
			error: null
		};
	
		postMessage(resp);
	}
};

//-------------------------------------------------------------------------------

EndUser.prototype.MakeError = function(e) {
	if (!e.GetMessage) {
		e = this.m_euSign.MakeError(EU_ERROR_UNKNOWN);
	}

	return {
		code: e.GetErrorCode(),
		message: e.GetMessage()
	};
};

//-------------------------------------------------------------------------------

EndUser.prototype.MakeURL = function(url) {
	if (url.indexOf('http://') == 0 ||
		url.indexOf('https://') == 0) {
		return url;
	}

	if ((url.indexOf('/') == 0) && s_origin) {
		return s_origin + url;
	}

	if (s_origin && s_pathname) {
		return s_origin + 
			s_pathname.substr(0, s_pathname.lastIndexOf('/')) + 
			'/' + url;
	}

	return url;
};

//-------------------------------------------------------------------------------

EndUser.prototype.DowloadData = function(url, dataType) {
	try {
		var xmlHttp = XMLHttpRequest ? 
			(new XMLHttpRequest()) : 
			new ActiveXObject("Microsoft.XMLHTTP");

		url = this.MakeURL(url);

		xmlHttp.open("GET", url, false);
		if (dataType == 'binary')
			xmlHttp.responseType = 'arraybuffer';
		xmlHttp.send();
		if (xmlHttp.status != 200) {
			throw 'Download data error. URL - ' + 
				url + ', status - ' + xmlHttp.status;
		}

		switch (dataType) {
			case 'binary':
				return new Uint8Array(xmlHttp.response);

			case 'json':
				return JSON.parse(xmlHttp.responseText.replace(/\\'/g, "'"));

			default:
				return xmlHttp.responseText;
		}
	} catch (e) {
		console.log("EndUser.DowloadData error: " + e);
		this.m_euSign.RaiseError(EU_ERROR_DOWNLOAD_FILE);
	}
};

//-------------------------------------------------------------------------------

EndUser.prototype.GetCASettings = function(CACommonName) {
	if (!CACommonName)
		return null;

	var CAs = this.m_settings.CAs;
	for (var i = 0; i < CAs.length; i++) {
		var issuerCNs = CAs[i].issuerCNs;
		for (var j = 0; j < issuerCNs.length; j++) {
			if (issuerCNs[j] == CACommonName)
				return CAs[i];
		}
	}

	return null;
};

//-------------------------------------------------------------------------------

EndUser.prototype.IsCMPCompatible = function(CA, compatibility) {
	if (!CA.cmpAddress)
		return false;

	if (typeof(CA.cmpCompatibility) !== 'undefined' &&
			(CA.cmpCompatibility & compatibility) != compatibility) {
		return false;
	}

	return true;
};

//-------------------------------------------------------------------------------

EndUser.prototype.SetSettings = function(CACommonName) {
	var euSign = this.m_euSign;
	var CAs = this.m_settings.CAs;
	var CASettings = this.GetCASettings(CACommonName);
	var CADefaultSettings = (CAs && (CAs.length > 0)) ? 
		CAs[0] : null;

	if (CACommonName && (CASettings == null)) {
		euSign.RaiseError(EU_ERROR_WRITE_SETTINGS);
		return;
	}

	var useTSP = true;
	var useOCSP = false;
	var useCMP = false;

	useOCSP = !CASettings ||
		!!(CASettings && CASettings.ocspAccessPointAddress);
	useCMP = !!(CASettings && CASettings.cmpAddress);

	var settings = euSign.CreateTSPSettings();
	settings.SetGetStamps(useTSP);
	if (useTSP) {
		var tspSettings = (CASettings && CASettings.tspAddress) ? 
			CASettings : CADefaultSettings;
		
		settings.SetAddress(tspSettings ? 
			tspSettings.tspAddress : "");
		settings.SetPort(tspSettings ? 
			tspSettings.tspAddressPort : "80");
	}

	euSign.SetTSPSettings(settings);

	settings = euSign.CreateOCSPSettings();
	settings.SetUseOCSP(useOCSP);
	if (useOCSP) {
		settings.SetBeforeStore(true);
		settings.SetAddress("czo.gov.ua");
		settings.SetPort("80");
	}
	euSign.SetOCSPSettings(settings);

	settings = euSign.CreateCMPSettings();
	settings.SetUseCMP(useCMP);
	if (useCMP) {
		settings.SetAddress(CASettings.cmpAddress);
		settings.SetPort("80");
	}
	euSign.SetCMPSettings(settings);
};

//-------------------------------------------------------------------------------

EndUser.prototype.CtxReadPrivateKeyBinaryInternal = function(
	context, privateKey, password, certs, CACommonName) {
	var pThis = this;
	var pkContext = null;
	var euSign = pThis.m_euSign;
	if (certs) {
		certs.forEach(function(cert) {
			euSign.SaveCertificate(cert);
		});
	}

	if (!context) {
		context = pThis.m_context;
	} else {
		context = EndUserInitFromTransferableObject(
			context, EndUserContext);
	}

	pThis.SetSettings(CACommonName);

	try {
		pkContext = euSign.CtxReadPrivateKeyBinary(
			context, privateKey, password);
		var info = pkContext.GetOwnerInfo();
		if (CACommonName) {
			var ca = pThis.GetCASettings(info.GetIssuerCN());
			if (!ca || (ca.issuerCNs.indexOf(CACommonName) == -1)) {
				euSign.CtxFreePrivateKey(pkContext);
				throw euSign.MakeError(EU_ERROR_CERT_NOT_FOUND);
			}
		} else {
			pThis.SetSettings(info.GetIssuerCN());
		}
	} catch (e) {
		if (e.GetErrorCode() != EU_ERROR_CERT_NOT_FOUND || CACommonName)
			throw e;

		var result = pThis.SearchPrivateKeyCertificatesWithCMP(
			privateKey, password);

		pThis.SetSettings(result.CACommonName);
		euSign.SaveCertificates(result.certs);
		pkContext = euSign.CtxReadPrivateKeyBinary(
			context, privateKey, password);
	}

	return pkContext;
};

//-------------------------------------------------------------------------------

EndUser.prototype.ReadPrivateKeyBinaryInternal = function(
	privateKey, password, certs, CACommonName) {
	var pThis = this;

	pThis.ResetPrivateKeyInternal();

	pThis.m_pkContext = pThis.CtxReadPrivateKeyBinaryInternal(
		pThis.m_context, privateKey, password, certs, CACommonName);
};

//-------------------------------------------------------------------------------

EndUser.prototype.ResetPrivateKeyInternal = function() {
	this.m_euSign.CtxFreePrivateKey(this.m_pkContext);
	this.m_pkContext = null;

	this.m_euKSP.ResetPrivateKey();
};

//-------------------------------------------------------------------------------

EndUser.prototype.SearchPrivateKeyCertificatesWithCMP = function(
	privateKey, password, caCN) {
	var pThis = this;
	var euSign = pThis.m_euSign;
	var CAs = pThis.m_settings.CAs;
	var keyInfo = euSign.GetKeyInfoBinary(privateKey, password);
	var certs = null;
	var isCAsAccessChecked = false;

	for (var i = 0; i < CAs.length; i++) {
		var cmpCompatibility = caCN ? 
			EU_CMP_COMPATIBILITY_DOWNLOAD_EU_CERTS : 
			EU_CMP_COMPATIBILITY_SEARCH_EU_CERTS;
		if (!pThis.IsCMPCompatible(CAs[i], cmpCompatibility))
			continue;

		if (caCN && CAs[i].issuerCNs.indexOf(caCN) == -1)
			continue;

		try {
			certs = euSign.GetCertificatesByKeyInfo(
				keyInfo, [CAs[i].cmpAddress + ":80"]);
		} catch (e) {
			var errorCode = e.GetErrorCode();

			if (errorCode == EU_ERROR_CERT_NOT_FOUND || 
					errorCode == EU_ERROR_TRANSMIT_REQUEST) {
				isCAsAccessChecked = isCAsAccessChecked || 
					(errorCode == EU_ERROR_CERT_NOT_FOUND);
				continue;
			}

			throw e;
		}

		return {
			"certs": certs, 
			"CACommonName": CAs[i].issuerCNs[0]
		};
	}
		
	throw euSign.MakeError(isCAsAccessChecked ? 
		EU_ERROR_CERT_NOT_FOUND : EU_ERROR_TRANSMIT_REQUEST);
};

//-------------------------------------------------------------------------------

EndUser.prototype.GetHashAlgoBySignAlgo = function(signAlgo) {
	var pThis = this;
	var euSign = pThis.m_euSign;

	switch (signAlgo) {
		case EU_CTX_SIGN_DSTU4145_WITH_GOST34311:
			return EU_CTX_HASH_ALGO_GOST34311;

		case EU_CTX_SIGN_RSA_WITH_SHA:
		case EU_CTX_SIGN_ECDSA_WITH_SHA:
			return EU_CTX_HASH_ALGO_SHA256;

		default:
			euSign.RaiseError(EU_ERROR_BAD_PARAMETER);
			break;
	}
};

//-------------------------------------------------------------------------------

EndUser.prototype.CtxSignHashInternal = function(
	pkContext, signAlgo, hash, previousSign, appendCert, asBase64String,
	onSuccess, onError) {
	var pThis = this;
	var euSign = pThis.m_euSign;

	try {
		if (pkContext == null) {
			euSign.RaiseError(EU_ERROR_BAD_CERT);
			return;
		}

		pkContext = EndUserInitFromTransferableObject(
			pkContext, EndUserPrivateKeyContext);

		var appendSign = previousSign != null;
		var hashes = DataToNamedDataArray(hash);
		var previousSigns = DataToNamedDataArray(previousSign);
		var signs = [];
	
		if (appendSign &&
			hashes.length != previousSigns.length) {
			euSign.RaiseError(EU_ERROR_BAD_PARAMETER);
			return;
		}

		for (var i = 0; i < hashes.length; i++) {
			var sign = appendSign ? 
				euSign.CtxAppendSignHashValue(
					pkContext, signAlgo, hashes[i].val, 
					previousSigns[i].val,
					appendCert, asBase64String) :
				euSign.CtxSignHashValue(
					pkContext, signAlgo, hashes[i].val, 
					appendCert, asBase64String);
			signs.push(sign);
		}

		var result = DataToResult(hash, signs);
		onSuccess(result);
	} catch (e) {
		onError(e);
	}
};

//-------------------------------------------------------------------------------

EndUser.prototype.CtxSignDataInternal = function(pkContext, 
	signAlgo, data, previousSign, external, appendCert, 
	asBase64String, onSuccess, onError) {
	var pThis = this;
	var euSign = pThis.m_euSign;

	try {
		if (pkContext == null) {
			euSign.RaiseError(EU_ERROR_BAD_CERT);
			return;
		}

		pkContext = EndUserInitFromTransferableObject(
			pkContext, EndUserPrivateKeyContext);

		var appendSign = previousSign != null;
		var datas = DataToNamedDataArray(data);
		var previousSigns = DataToNamedDataArray(previousSign);
		var signs = [];
	
		if (appendSign && external && 
			datas.length != previousSigns.length) {
			euSign.RaiseError(EU_ERROR_BAD_PARAMETER);
			return;
		}

		var length = appendSign && !external ? 
			previousSigns.length : datas.length;
		for (var i = 0; i < length; i++) {
			var sign = null;

			if (external) {
				var hashAlgo = pThis.GetHashAlgoBySignAlgo(signAlgo);
				var hash = euSign.CtxHashData(
					pThis.m_context, hashAlgo, null, 
					datas[i].val, true);

				if (appendSign) {
					sign = euSign.CtxAppendSignHashValue(
						pkContext, signAlgo, hash, 
						previousSigns[i].val,
						appendCert, asBase64String);
				} else {
					sign = euSign.CtxSignHashValue(
						pkContext, signAlgo, hash, 
						appendCert, asBase64String);
				}
			} else {
				if (appendSign) {
					sign = euSign.CtxAppendSign(
						pkContext, signAlgo, null, 
						previousSigns[i].val,
						appendCert, asBase64String);
				} else {
					sign = euSign.CtxSignData(
						pkContext, signAlgo, datas[i].val, 
						external, appendCert, asBase64String);
				}
			}

			signs.push(sign); 
		}

		var result = DataToResult(
			appendSign && !external ? 
				previousSign : data, signs);
		onSuccess(result);
	} catch (e) {
		onError(e);
	}
};

//-------------------------------------------------------------------------------

EndUser.prototype.LoadTaxReportPKey = function(pkCtxs, keyUsages, isStamp) {
	var pThis = this;
	var euSign = pThis.m_euSign;

	if (!Array.isArray(pkCtxs))
		pkCtxs = [pkCtxs];

	if (pkCtxs.length > 2)
		throw euSign.MakeError(EU_ERROR_BAD_PARAMETER);

	for (var i = 0; i < pkCtxs.length; i++) {
		pkCtxs[i] = EndUserInitFromTransferableObject(
			pkCtxs[i], EndUserPrivateKeyContext);
	}

	var pKey = new TaxReportPKey(); 

	for (var i = 0; i < keyUsages.length; i++) {
		var keyUsage = keyUsages[i];
		var pkCtx = null;
		var cert = null;

		for (var j = 0; j < pkCtxs.length; j++) {
			try {
				pkCtx = pkCtxs[j];
				cert = euSign.CtxGetOwnCertificate(
					pkCtx, EU_CERT_KEY_TYPE_DSTU4145, keyUsage);
			} catch (e) {
				pkCtx = null;
				cert = null;
			}

			if (cert == null)
				continue;

			if (isStamp && 
				(keyUsage & EU_KEY_USAGE_DIGITAL_SIGNATURE) && 
				!(cert.GetInfoEx().GetExtKeyUsages().indexOf(
					UA_OID_EXT_KEY_USAGE_STAMP) > -1)) {
				throw euSign.MakeError(EU_ERROR_BAD_PARAMETER);
			}

			break;
		}

		if (cert == null)
			throw euSign.MakeError(EU_ERROR_BAD_PARAMETER);

		if (keyUsage & EU_KEY_USAGE_DIGITAL_SIGNATURE) {
			pKey.signPKCtx = pkCtx;
			pKey.signCert = cert;
		} else if (keyUsage & EU_KEY_USAGE_KEY_AGREEMENT) {
			pKey.envelopPKCtx = pkCtx;
			pKey.envelopCert = cert;
		} else {
			throw euSign.MakeError(EU_ERROR_BAD_PARAMETER);
		}
	}

	return pKey;
};

//-------------------------------------------------------------------------------

EndUser.prototype.ProtectTaxReport = function(
	accountantPKey, directorPKey, stampPKey,
	senderEMail, recipientCertificate, report, 
	returnIntermediateSign) {
	var euSign = this.m_euSign;

	var result = {
		"name": report.name, 
		"data": null, 
		"error": null
	};
	try {
		var _sign = function(pKey, data) {
			data = euSign.CtxSignData(pKey.signPKCtx, 
				EU_CTX_SIGN_DSTU4145_WITH_GOST34311, 
				data, false, true);
			return euSign.AppendCryptoHeader(
				EU_HEADER_CA_TYPE, 
				EU_HEADER_PART_TYPE_SIGNED, data);
		};

		var _isMultiCert = function(cert) {
			var keyUsage = EU_KEY_USAGE_DIGITAL_SIGNATURE | 
				EU_KEY_USAGE_KEY_AGREEMENT;

			return (keyUsage == (cert.GetInfoEx().
				GetKeyUsageType() & keyUsage));
		};

		var reportData = report.data;
		var ownCert;

		if (accountantPKey != null)
			reportData = _sign(accountantPKey, reportData);
		
		if (directorPKey != null)
			reportData = _sign(directorPKey, reportData);
		
		if (stampPKey != null)
			reportData = _sign(stampPKey, reportData);
		
		if (returnIntermediateSign)
			result.signedData = reportData;

		if (directorPKey != null || stampPKey != null) {
			var pKey = (stampPKey != null) ? 
				stampPKey : directorPKey;

			reportData = euSign.CtxEnvelopData(
				pKey.envelopPKCtx, [recipientCertificate],
				EU_RECIPIENT_APPEND_TYPE_BY_ISSUER_SERIAL,
				false, false, reportData);
			
			reportData = euSign.AppendCryptoHeader(
				EU_HEADER_CA_TYPE, 
				EU_HEADER_PART_TYPE_ENCRYPTED, reportData);
			
			ownCert = pKey.envelopCert;
			
			if (!_isMultiCert(ownCert)) {
				var certHeader = euSign.AppendCryptoHeader(
					EU_HEADER_CA_TYPE, 
					EU_HEADER_PART_TYPE_CERTCRYPT, 
					ownCert.GetData());

				var tmp = new Uint8Array(certHeader.byteLength + 
					reportData.byteLength);
				tmp.set(new Uint8Array(certHeader), 0);
				tmp.set(new Uint8Array(reportData), certHeader.byteLength);

				reportData = tmp;
			}

			reportData = _sign(pKey, reportData);
		} else {
			ownCert = accountantPKey.signCert;
		}

		reportData = euSign.AppendTransportHeader(
			EU_HEADER_CA_TYPE, report.name, senderEMail,
			ownCert.GetData(), reportData);

		result.data = reportData;
		result.error = this.MakeError(
			euSign.MakeError(EU_ERROR_NONE));
	} catch (e) {
		result.error = this.MakeError(e);
	}

	return result;
};

//-------------------------------------------------------------------------------

EndUser.prototype.UnprotectTaxReceipt = function(
	directorOrStampPrivateKeyContext, receipt) {
	var euSign = this.m_euSign;

	var result = {
		"data": null, 
		"receiptNumber": 0,
		"initiators": [],
		"error": null
	};
	try {
		var receiptData = receipt.data;
		var headerInfo = null;

		try {
			headerInfo = euSign.ParseTransportHeader(receiptData);
			result.receiptNumber = headerInfo.GetReceiptNumber();
			receiptData = headerInfo.GetCryptoData();
		} catch (e) {
			if (e.GetErrorCode() != EU_ERROR_PKI_FORMATS_FAILED) {
				throw e;
			}
		}

		while (true) {
			try {
				headerInfo = euSign.ParseCryptoHeader(receiptData);
			} catch (e) {
				if (e.GetErrorCode() != EU_ERROR_BAD_PARAMETER) {
					throw e;
				}
				
				break;
			}

			var cryptoData = headerInfo.GetCryptoData();

			switch (headerInfo.GetHeaderType()) {
				case EU_HEADER_PART_TYPE_SIGNED:
					var signInfo = euSign.CtxVerifyDataInternal(
						this.m_context, 0, cryptoData);
					receiptData = signInfo.GetData();
					signInfo.data = null;
					signInfo = signInfo.GetTransferableObject();
					signInfo.signLevel = euSign.GetSignType(0, cryptoData);
					result.initiators.push(signInfo);
				break;
				
				case EU_HEADER_PART_TYPE_ENCRYPTED:
					var senderInfo = euSign.CtxDevelopData(
						directorOrStampPrivateKeyContext, 
						cryptoData, null);
					receiptData = senderInfo.GetData();
					senderInfo.data = null;
					result.initiators.push(
						senderInfo.GetTransferableObject());
				break;

				case EU_HEADER_PART_TYPE_STAMPED:
				case EU_HEADER_PART_TYPE_CERTCRYPT:
					receiptData = receiptData.slice(
						headerInfo.GetHeaderSize() + cryptoData.length,
						receiptData.length);
				break;

				default:
					euSign.RaiseError(EU_ERROR_PKI_FORMATS_FAILED);
			}
		}

		result.data = receiptData;
		result.error = this.MakeError(
			euSign.MakeError(EU_ERROR_NONE));
	} catch (e) {
		result.error = this.MakeError(e);
	}

	return result;
};

//===============================================================================

EndUser.prototype.GetLibraryInfo = function(
	downloadsURL, onSuccess, onError) {
	try {
		var info = {
			"version": this.m_euSign.GetVersion(),
			"supported": true,
			"loaded": true
		};

		onSuccess(info);
	} catch (e) {
		onError(e);
	}
};

//-------------------------------------------------------------------------------

EndUser.prototype.IsInitialized = function(onSuccess, onError) {
	onSuccess(this.m_initialized);
};

//-------------------------------------------------------------------------------

EndUser.prototype.Initialize = function(settings, onSuccess, onError) {
	var pThis = this;
	var euSign = pThis.m_euSign;
	var KSPs, i;

	try {
		if (typeof settings.CAs === 'string') {
			settings.CAs = 
				pThis.DowloadData(settings.CAs, 'json');
		}

		if (typeof settings.CACertificates === 'string') {
			settings.CACertificates = 
				pThis.DowloadData(settings.CACertificates, 'binary');
		}

		if (typeof settings.signInfoTmpl === 'string') {
			settings.signInfoTmpl = 
				pThis.DowloadData(settings.signInfoTmpl, '');
		}

		pThis.m_settings = settings;

		euSign.SetErrorMessageLanguage(settings.language);
		euSign.SetCharset(settings.encoding);
		euSign.SetJavaStringCompliant(true);

		euSign.Initialize();
		if(settings.ocspResponseExpireTime){
			euSign.SetOCSPResponseExpireTime(
				settings.ocspResponseExpireTime);
		}
		pThis.m_context = euSign.CtxCreate();

		if (settings.httpProxyServiceURL) {
			euSign.SetXMLHTTPProxyService(
				pThis.MakeURL(settings.httpProxyServiceURL));
		}

		euSign.SetRuntimeParameter(
			EU_RESOLVE_OIDS_PARAMETER, false);
		euSign.CtxSetParameter(pThis.m_context, 
			EU_RESOLVE_OIDS_CONTEXT_PARAMETER, false);
		euSign.SetRuntimeParameter(
			EU_CHECK_CERT_CHAIN_ON_SIGN_TIME_PARAMETER, true);

		euSign.InitializeMandatorySettings();

		var mode = euSign.CreateModeSettings();
		mode.SetOfflineMode(false);
		euSign.SetModeSettings(mode);

		var fs = euSign.CreateFileStoreSettings();
		fs.SetPath('');
		fs.SetSaveLoadedCerts(true);
		euSign.SetFileStoreSettings(fs);

		if (settings.CACertificates != null)
			euSign.SaveCertificates(settings.CACertificates);

		var ocsp = euSign.CreateOCSPSettings();
		ocsp.SetUseOCSP(true);
		ocsp.SetBeforeStore(true);
		ocsp.SetAddress("czo.gov.ua");
		ocsp.SetPort("80");
		euSign.SetOCSPSettings(ocsp);

		var CAs = settings.CAs;
		var ocspMode = euSign.CreateOCSPAccessInfoModeSettings();
		ocspMode.SetEnabled(true);
		euSign.SetOCSPAccessInfoModeSettings(ocspMode);
		var ocspAccessInfo = euSign.CreateOCSPAccessInfoSettings();
		for (i = 0; i < CAs.length; i++) {
			ocspAccessInfo.SetAddress(CAs[i].ocspAccessPointAddress);
			ocspAccessInfo.SetPort(CAs[i].ocspAccessPointPort);

			for (var j = 0; j < CAs[i].issuerCNs.length; j++) {
				ocspAccessInfo.SetIssuerCN(CAs[i].issuerCNs[j]);
				euSign.SetOCSPAccessInfoSettings(ocspAccessInfo);
			}
		}

		var useTSL = !!settings.TSLAddress;
		if (useTSL) {
			var tsl = euSign.CreateTSLSettings();
			tsl.SetUseTSL(useTSL);
			tsl.SetAutoDownloadTSL(useTSL ? true : false);
			tsl.SetTSLAddress(useTSL ? settings.TSLAddress : '');
			euSign.SetTSLSettings(tsl);
		}

		var _addDNSName = function(uri, dnsNames) {
			if (uri == '')
				return;

			uri = (uri.indexOf("://") > -1) ? 
				uri.split('/')[2] : 
				uri.split('/')[0];

			if (dnsNames.indexOf(uri) >= 0)
				return;

			dnsNames.push(uri);
		};

		euSign.SetXMLHTTPDirectAccess(settings.directAccess);
		if (settings.directAccess) {
			var directAccessURLs = Array();
			_addDNSName('czo.gov.ua', directAccessURLs);
			for (i = 0; i < CAs.length; i++) {
				if (!CAs[i].directAccess)
					continue;

				_addDNSName(CAs[i].address, directAccessURLs);
				_addDNSName(CAs[i].tspAddress, directAccessURLs);
				_addDNSName(CAs[i].cmpAddress, directAccessURLs);
				_addDNSName(CAs[i].ocspAccessPointAddress,
					directAccessURLs);
			}
			
			KSPs = settings.KSPs || null;
			if (KSPs) {
				for (i = 0; i < KSPs.length; i++) {
					if (!KSPs[i].directAccess)
						continue;

					_addDNSName(KSPs[i].address, directAccessURLs);
				}
			}

			directAccessURLs.forEach(function(address) {
				euSign.AddXMLHTTPDirectAccessAddress(address);
			});
		}

		var mssServiceURL = pThis.MakeURL(settings.mssServiceURL || "");
		KSPs = settings.KSPs || null;
		pThis.m_euKSP = new EndUserKSP(mssServiceURL, KSPs,
			pThis.m_euSign, pThis.m_context, 
			function(event) {
				pThis.OnEvent(event);
			});

		pThis.m_initialized = true;

		onSuccess();
	} catch (e) {
		onError(e);
	}
};

//-------------------------------------------------------------------------------

EndUser.prototype.AddEventListener = function(
	eventType, onSuccess, onError) {
	var pThis = this;
	var supportedEvents = [
		EndUserEventType.None,
		EndUserEventType.All,
		EndUserEventType.ConfirmKSPOperation
	];

	try {
		if (supportedEvents.indexOf(eventType) < 0)
			throw pThis.m_euSign.MakeError(EU_ERROR_BAD_PARAMETER);
		
		switch (eventType) {
			case EndUserEventType.None:
				pThis.m_eventListeners = [];
				break;
			case EndUserEventType.All:
				pThis.m_eventListeners = [];
				pThis.m_eventListeners[eventType] = function(event) {
					pThis.OnEvent(event);
				};
				break;

			default:
				pThis.m_eventListeners[eventType] = function(event) {
					pThis.OnEvent(event);
				};
				break;
		}

		onSuccess();
	} catch (e) {
		onError(e);
	}
};

