//-------------------------------------------------------------------------------

EndUser.prototype.ProtectTaxReports = function(
	accountantPrivateKeyContext, directorPrivateKeyContext, 
	stampPrivateKeyContext, senderEMail, recipientCertificate, 
	reports, returnIntermediateSign, onSuccess, onError) {
	var pThis = this;
	try {
		var accountantPKey = null;
		var directorPKey = null;
		var stampPKey = null;
		var keyUsages;

		if (accountantPrivateKeyContext) {
			keyUsages = [EU_KEY_USAGE_DIGITAL_SIGNATURE];

			accountantPKey = pThis.LoadTaxReportPKey(
				accountantPrivateKeyContext, keyUsages, false);
			if (accountantPKey == null) {
				throw pThis.m_euSign.MakeError(EU_ERROR_BAD_PARAMETER);
			}
		}

		if (directorPrivateKeyContext) {
			keyUsages = [EU_KEY_USAGE_DIGITAL_SIGNATURE];
			if (!stampPrivateKeyContext)
				keyUsages.push(EU_KEY_USAGE_KEY_AGREEMENT);

			directorPKey = pThis.LoadTaxReportPKey(
				directorPrivateKeyContext, keyUsages, false);
			if (directorPKey == null) {
				throw pThis.m_euSign.MakeError(EU_ERROR_BAD_PARAMETER);
			}
		}

		if (stampPrivateKeyContext) {
			keyUsages = [EU_KEY_USAGE_DIGITAL_SIGNATURE, 
				EU_KEY_USAGE_KEY_AGREEMENT];

			stampPKey = pThis.LoadTaxReportPKey(
				stampPrivateKeyContext, keyUsages, true);
			if (stampPKey == null) {
				throw pThis.m_euSign.MakeError(EU_ERROR_BAD_PARAMETER);
			}
		}

		var results = [];

		for (var i = 0; i < reports.length; i++) {
			var result = pThis.ProtectTaxReport(
				accountantPKey, directorPKey, stampPKey, 
				senderEMail, recipientCertificate, reports[i], 
				returnIntermediateSign);
			results.push(result);
		}

		onSuccess(results);
	} catch (e) {
		onError(e);
	}
};

//-------------------------------------------------------------------------------

EndUser.prototype.UnprotectTaxReceipts = function(
	directorOrStampPrivateKeyContext, receipts, onSuccess, onError) {
	try {
		directorOrStampPrivateKeyContext = EndUserInitFromTransferableObject(
			directorOrStampPrivateKeyContext, EndUserPrivateKeyContext);

		var results = [];

		for (var i = 0; i < receipts.length; i++) {
			var result = this.UnprotectTaxReceipt(
				directorOrStampPrivateKeyContext, receipts[i]);
			results.push(result);
		}

		onSuccess(results);
	} catch (e) {
		onError(e);
	}
};

