EndUser.prototype.ASiCGetSigner = function(
	asicData, signIndex, resolveOIDs, onSuccess, onError) {
	var euSign = this.m_euSign;
	var context = null;

	try {
		var signerInfo = null;
		var result = null;

		signIndex = GetOptionalParam(signIndex, -1);
		resolveOIDs = GetOptionalParam(resolveOIDs, false);

		context = euSign.CtxCreate();
		euSign.CtxSetParameter(context, 
			EU_RESOLVE_OIDS_CONTEXT_PARAMETER, resolveOIDs);

		if (signIndex == -1) {
			result = [];
			var signCount = euSign.ASiCGetSignsCount(asicData);
			for (var i = 0; i < signCount; i++) {
				signerInfo = euSign.CtxASiCGetSignerInfo(
					context, i, asicData);
				result.push(signerInfo.GetTransferableObject());
			}
		} else {
			signerInfo = euSign.CtxASiCGetSignerInfo(
				context, signIndex, asicData);
			result = signerInfo.GetTransferableObject();
		}
		
		euSign.CtxFree(context);

		onSuccess(result);
	} catch (e) {
		if (context)
			euSign.CtxFree(context);

		onError(e);
	}
};

//-------------------------------------------------------------------------------

EndUser.prototype.ASiCSignData = function(
	signAlgo, asicType, signType, signLevel, references,
	asBase64String, onSuccess, onError) {
	if (this.m_euKSP.IsPrivateKeyReaded()) {
		this.m_euKSP.ASiCSignData(
			signAlgo, asicType, signType, signLevel, references,
			asBase64String, onSuccess, onError);
		return;
	}

	var pThis = this;
	var euSign = pThis.m_euSign;
	var pkContext = pThis.m_pkContext;

	try {
		if (pkContext == null) {
			euSign.RaiseError(EU_ERROR_BAD_CERT);
			return;
		}

		pkContext = EndUserInitFromTransferableObject(
			pkContext, EndUserPrivateKeyContext);

		references = DataToNamedDataArray(references);
		var asicReferences = [];
		for (var i = 0; i < references.length; i++) {
			var reference = new EndUserReference(
				references[i].name, references[i].val);
			asicReferences.push(reference);
		}

		var asicData = euSign.CtxASiCSignData(pkContext, 
			signAlgo, asicType, signType, signLevel,
			asicReferences, asBase64String);
		var result = {
			name: references[0].name + 
				(asicType == EU_ASIC_TYPE_S ? 
					'.asics' : '.asice'),
			val: asicData
		};
		onSuccess(result);
	} catch (e) {
		onError(e);
	}
};

//-------------------------------------------------------------------------------

EndUser.prototype.ASiCAppendSign = function(
	signAlgo, signLevel, referencesNames, asicData,
	asBase64String, onSuccess, onError) {
	if (this.m_euKSP.IsPrivateKeyReaded()) {
		this.m_euKSP.ASiCAppendSign(
			signAlgo, signLevel, referencesNames, asicData,
			asBase64String, onSuccess, onError);
		return;
	}

	var pThis = this;
	var euSign = pThis.m_euSign;
	var pkContext = pThis.m_pkContext;

	try {
		if (pkContext == null) {
			euSign.RaiseError(EU_ERROR_BAD_CERT);
			return;
		}

		pkContext = EndUserInitFromTransferableObject(
			pkContext, EndUserPrivateKeyContext);

		var previousASiCData = DataToNamedDataArray(asicData);

		asicData = euSign.CtxASiCAppendSign(pkContext, 
			signAlgo, signLevel, referencesNames,
			previousASiCData[0].val, asBase64String);
		var result = {
			name: previousASiCData[0].name,
			val: asicData
		};
		onSuccess(result);
	} catch (e) {
		onError(e);
	}
};

